namespace Playarr.Tizen;

// Generated by scripts/parity/tizen-native/baseline-shifts.cjs: how far (px, up) a single-line label must move so its baseline lands where
// Chromium puts the same text. Measured: median of the best vertical shift of every web text box (scripts/parity/tizen-native/baseline-shifts.cjs).
internal static class BaselineShifts
{
    private static readonly SortedDictionary<float, float> Table = new()
    {
        [8.256f] = 1f,
        [8.832f] = 0.5f,
        [9.6f] = 0.25f,
        [9.92f] = 0.25f,
        [9.984f] = 1f,
        [10.56f] = 0.25f,
        [11.136f] = 1f,
        [11.52f] = 0.75f,
        [11.904f] = 0.75f,
        [12.288f] = 0f,
        [12.8f] = 1.5f,
        [12.864f] = 0.75f,
        [13.056f] = 0.75f,
        [13.44f] = 1.5f,
        [13.824f] = 0.25f,
        [14.72f] = 0f,
        [17.28f] = 1f,
        [17.664f] = 0.25f,
        [18.4f] = 0.25f,
        [19.2f] = 1f,
        [26.4f] = 0.5f,
        [29.6f] = 0.5f,
        [33.6f] = 0.5f,
        [69.12f] = -1f
    };

    public static float Up(float size)
    {
        if (Table.Count == 0) return 0;
        var best = Table.Keys.OrderBy(k => Math.Abs(k - size)).First();
        return Math.Abs(best - size) <= 0.01f ? Table[best] : 0;
    }
}
